def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v2 == 0:
        return None

    ratio = v1 / v2
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "v1": v1,
            "v2": v2,
            "ratio": ratio,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
